function countSteps(n) {
  let single = 0
  for (let i = 0; i < n; i++) single++
  let nested = 0
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) nested++
  }
  return [single, nested]
}
for (const n of [10, 100, 1000]) console.log(n, countSteps(n))

